<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Media;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class MediaController extends Controller{public function index(Request $r){$q=Media::latest();if($r->filled('q'))$q->where('name','like','%'.$r->q.'%');return view('admin.media.index',['media'=>$q->paginate(36)->withQueryString()]);}public function store(Request $r){$r->validate(['files'=>'required','files.*'=>'file|max:51200','alt'=>'nullable|max:255']);foreach($r->file('files') as $file){$path=$file->store('media/'.date('Y/m'),'public');Media::create(['user_id'=>auth()->id(),'name'=>$file->getClientOriginalName(),'disk'=>'public','path'=>$path,'mime'=>$file->getMimeType(),'size'=>$file->getSize(),'alt'=>$r->alt]);}return back()->with('success','Файлы загружены');}public function destroy(Media $media){Storage::disk($media->disk)->delete($media->path);$media->delete();return back()->with('success','Файл удалён');}}
